import 'dart:ui';

import 'package:path_parsing/path_parsing.dart';

/// A full-color drawing as SVG path data on a square canvas [size] units wide.
class SeasonalArtwork {
  const SeasonalArtwork(this.size, this.paths);

  final double size;

  /// Fill color and path data, painted in order.
  final List<(int, String)> paths;

  /// Paints the drawing to fill a square [extent] units wide from the canvas origin.
  void paint(Canvas canvas, double extent) {
    canvas.save();
    canvas.scale(extent / size);
    for (final (color, data) in paths) {
      final path = Path();
      writeSvgPathDataToPath(data, _PathWriter(path));
      canvas.drawPath(path, Paint()..color = Color(color));
    }
    canvas.restore();
  }

